-- PeaklyTest Oct 2024 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('efa83eec-222c-5008-9e62-ab823466d788', 'PeaklyTest Oct 2024 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Oct 2024 PeaklyTest · 27 questions · 32 minutes', 32, 260, true, 'PeaklyTest Oct 2024 · Reading & Writing', 1)
