insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('3d1764c5-89b1-593f-aee3-15ba42e0cce6', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The table summarizes members of a local organization by age and whether they live north or south of Center St., If a member of the organization is selected at random, what is the probability that the selected member is at least 45 years old?', '["$\\frac{30}{135}$", "$\\frac{35}{135}$", "$\\frac{100}{135}$", "$\\frac{105}{135}$"]'::jsonb, 1, '|  | Live north of Center St. | Live south of Center St. | Total |
| Less than 45 years old | $15$ | $15$ | $30$ |
| At least 45 years old | $20$ | $85$ | $105$ |
| Total | $35$ | $100$ | $135$ |'),
  ('46be7793-4baf-50a7-8701-01a4d89756a9', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'Which expression is equivalent to $4(x^{2} + 6)$?', '["$4x^{2} + 24$", "$4x^{2} + 10$", "$4x^{2} + 6$", "$4x^{2} - 2$"]'::jsonb, 2, null),
  ('17ab76c3-99be-55ec-9d37-f45da3564e56', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'For the linear function $f$, the graph of $y = f(x)$ in the $xy$-plane has a slope of $\frac{1}{4}$ and passes through the point $(0,5)$, which equation defines $f$?', '["$f(x) = \\frac{1}{4}x + 5$", "$f(x) = \\frac{1}{4}x + \\frac{1}{5}$", "$f(x) = \\frac{1}{4}x - \\frac{5}{4}$", "$f(x) = \\frac{1}{4}x - 5$"]'::jsonb, 3, null),
  ('5f3049f2-68f4-569b-807c-9981cc1f508f', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The function $f$ is defined by $f(x) = 5 +\sqrt{x}$. What is the value of $f(144)$?', '[]'::jsonb, 4, null),
  ('c3213018-66eb-5fa0-8f3d-e59106993014', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'For the given equation, which table gives three values of $x$ and their corresponding values of $y$?
$7x - 4y = -84$', '["| x | 0 | 4 | 8 |\n| y | 21 | 28 | 35 |", "| x | 0 | 4 | 8 |\n| y | 35 | 28 | 21 |", "| x | 21 | 28 | 35 |\n| y | 0 | 4 | 8 |", "| x | 21 | 28 | 35 |\n| y | 8 | 4 | 0 |"]'::jsonb, 5, null),
  ('ad2f07d1-247e-578e-b839-0a16a4f5eb9d', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'A geologist estimates that the volume of a boulder is greater than $12.7$ cubic feet but less than $15.7$ cubic feet. The geologist also estimates that the boulder weighs $160$ pounds per cubic foot of volume. Which inequality represents this situation, where $x$ represents the estimated total weight, in pounds, of the boulder?', '["$160 - 15.7 < x < 160 - 12.7$", "$160 + 12.7 < x < 160 + 15.7$", "$160(12.7) < x < 160(15.7)$", "$\\frac{160}{15.7} < x < \\frac{160}{12.7}$"]'::jsonb, 6, null),
  ('05b3aa9c-0a46-5028-9003-5038a8bb55b6', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'If $46 = 16 + 2(x - 8)$, what is the value of $2(x - 8)$?', '["$16$", "$23$", "$30$", "$38$"]'::jsonb, 7, null),
  ('d31c568a-ba3d-508b-b008-1472c61fcd90', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', '$y = x^{2} + 1.7$
$y = 1.7 - x$
Which graph represents the given system of equations?', '["![figure](/q/oct24/002.webp)", "![figure](/q/oct24/003.webp)", "![figure](/q/oct24/004.webp)", "![figure](/q/oct24/005.webp)"]'::jsonb, 8, null),
  ('7ea3d3c5-1b7d-53c9-a764-6daf5f966787', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'In triangle ABC, the measure of angle A is $47°$, the measure of angle B is $90°$, and the measure of angle C is $(\frac{k}{2})°$. What is the value of $k$?', '["$43$", "$45$", "$86$", "$94$"]'::jsonb, 9, null),
  ('518db9ab-66b3-576b-abd0-986f6c6fcbb9', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'A clothing store buys shirts at a wholesale price of \$5.00 each and resells them each at a retail price that is $270%$ of the wholesale price. At the end of the season, any remaining shirts are marked at a discounted price that is $70%$ off the retail price. What is the discounted price of each remaining shirt, in dollars?', '[]'::jsonb, 10, null),
  ('29449225-b4e3-5a13-b1c5-5483876825c9', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'Which of the following is closest to the slope of this line of best fit?', '["$-3.3$", "$-1.1$", "$1.1$", "$3.3$"]'::jsonb, 11, '![figure](/q/oct24/006.webp)'),
  ('025f36e5-e5b3-58c3-a2cf-edca5521ce69', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The expression $72y^{5} - 48y^{4}$ is equivalent to $ry^{4}(12y - 8)$, where $r$ is a constant. What is the value of $r$ ?', '[]'::jsonb, 12, null),
  ('0ab95b69-88d3-5990-a55c-ee986392ab40', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The equation gives the estimated stock price $y$, in dollars, for a certain company $x$ days after the company went public, where $0 \le x < 20$. Which statement is the best interpretation of $(x,y) =$ $(1,58)$ in this context?
$y = 0.25x^{2} - 6.5x + 64.25$', '["1 day after the company went public, the company’s estimated stock price is \\$58.", "58 days after the company went public, the company’s estimated stock price \\$1.", "The company’s estimated stock price increased \\$58 every day after the company went public.", "The company’s estimated stock price increased \\$1 every 58 days after the company went public."]'::jsonb, 13, null),
  ('fd028115-e71b-5415-9e14-68df377d3b27', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The total mass, in kilograms, of $r$ identical objects is $t$. Which expression represents the total mass, in kilograms, of $146r$ of these objects?', '["$146 - t$", "$146 + t$", "$\\frac{t}{146}$", "$146t$"]'::jsonb, 14, null),
  ('8a912cb4-5ca8-5d13-b2dc-757ca4b8b391', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'If $\frac{42}{x} = 7x$, what is the value of $7x^{2}$?', '["$6$", "$7$", "$42$", "$294$"]'::jsonb, 15, null),
  ('18262712-779e-5460-b2af-2397a1a2a107', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'Line $k$ is shown in the $xy$-plane. Line $j$ (not shown) is perpendicular to line $k$. What is the slope of line $j$?', '[]'::jsonb, 16, '![figure](/q/oct24/007.webp)'),
  ('4623a5de-1f32-5ea7-84ec-ffcac0db1993', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The function $f$ is defined by $f(x) = -9x + 9$. What is the $y$-coordinate of the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?', '[]'::jsonb, 17, null),
  ('599b089b-09ec-5563-95c3-08ff5ea4da2c', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The equation $h = \frac{9(v-273.15)}{5} + 12$ gives the corresponding temperature $h$, in degrees Fahrenheit, of any substance that has a temperature of $v$ kelvins, where $v > 0$. If a substance has a temperature of $467.33$ degrees Fahrenheit, what is the corresponding temperature, in kelvins, of this substance?', '[]'::jsonb, 18, null),
  ('3d2947f4-79b7-5804-9f14-0f76b60c9e20', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'A circle in the $xy$-plane has its center at $(16,17)$ and has a radius of $7k$. Which equation represents this circle?', '["$(x - 16)^{2} + (y - 17)^{2} = 49k$", "$(x - 16)^{2} + (y - 17)^{2} = 49k^{2}$", "$(x - 16)^{2} + (y - 17)^{2} = 7k$", "$(x - 16)^{2} + (y - 17)^{2} = 7x^{2}$"]'::jsonb, 19, null),
  ('15270349-d99c-55f0-b5ae-fd8c59f9c21a', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'In the triangle shown, $RS =\sqrt{105}$. What is the value of $\sin R$?', '[]'::jsonb, 20, '![figure](/q/oct24/008.webp)'),
  ('c12e5fc0-ccfa-50a2-8a6d-b49e9a1d0150', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'Parallelogram $ABCD$ is similar to parallelogram $PQRS$. The length of each side of parallelogram $PQRS$ is $2$ times the length of its corresponding side of parallelogram $ABCD$. The area of parallelogram $ABCD$ is $5$ square centimeters. What is the area, in square centimeters, of parallelogram $PQRS$?', '["$7$", "$10$", "$20$", "$25$"]'::jsonb, 21, null),
  ('84e6dac6-feb4-5b09-9955-41e27942a863', '9fda9f50-5c6f-50d4-94ec-251faaaa4dea', 'The function $r$ is defined by the given equation. The function $s$ is defined by $s(t) = r(t) + 1$. Which expression represents the maximum value of $s(t)$?
$r(t) = 55t - 2t^{2}$', '["$1 + (\\frac{55}{2})^{2}$", "$1 + 2(\\frac{55}{4})^{2}$", "$1 - 2(\\frac{55}{4})^{2}$", "$1 - 2(\\frac{55}{2})^{2}$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('3d1764c5-89b1-593f-aee3-15ba42e0cce6', 3, null, '**Choice D is correct.** The table shows that there are $105$ members who are at least 45 years old out of a total of $135$ members, so the probability is $\frac{105}{135}$.
**Choice A is incorrect.** $\frac{30}{135}$ is the fraction for members less than 45 years old (the row total $30$), not for members at least 45.
**Choice B is incorrect.** $\frac{35}{135}$ is the column total for those who live north of Center St., not the count of members at least 45.
**Choice C is incorrect.** $\frac{100}{135}$ is the column total for those who live south of Center St., not the number of members at least 45.
**Faster approach:** Use the age row totals — read the total in the "At least 45" row (105) and divide by the grand total (135) to get the probability immediately.'),
  ('46be7793-4baf-50a7-8701-01a4d89756a9', 0, null, '**Choice A is correct.** Distribute the 4 across the sum: $4(x^{2} + 6) = 4 \cdot x^{2} + 4 \cdot 6 = 4x^{2} + 24$, so $4x^{2} + 24$ is equivalent.
**Choice B is incorrect.** Multiplying gives $4x^{2} + 24$, not $4x^{2} + 10$; there is no operation that produces $+10$ from $4 \cdot 6$.
**Choice C is incorrect.** $4x^{2} + 6$ would result from adding 6 after multiplying $x^{2}$ by 4, but you must multiply the entire parenthesis by 4, giving $+24$, not $+6$.
**Choice D is incorrect.** $4x^{2} - 2$ has the wrong constant term and sign; distribution produces a positive $+24$, not $-2$.
**Faster approach:** Apply the distributive property immediately: multiply the coefficient outside the parentheses by each term inside to get the equivalent expression.'),
  ('17ab76c3-99be-55ec-9d37-f45da3564e56', 0, null, '**Choice A is correct.** A linear function in slope-intercept form is $f(x) = mx + b$, where $m$ is the slope and $b$ is the $y$-intercept. The slope is $\frac{1}{4}$ and the graph passes through $(0,5)$, which means the $y$-intercept is $5$. Substituting gives $f(x) = \frac{1}{4}x + 5$, so choice A is correct.
**Choice B is incorrect.** It has the correct slope but a $y$-intercept of $1/5$ rather than $5$, so it does not pass through $(0,5)$.
**Choice C is incorrect.** Although the slope $\frac{1}{4}$ is correct, the constant term $-\frac{5}{4}$ gives a $y$-intercept of $-\frac{5}{4}$, not $5$.
**Choice D is incorrect.** This choice also uses the correct slope but a $y$-intercept of $-5$, which contradicts the given point $(0,5)$.
**Faster approach:** Use slope-intercept form $y = mx + b$ and plug in the given point $(0,5)$ immediately to read off $b = 5$; combine with $m = \frac{1}{4}$ to get the answer.'),
  ('5f3049f2-68f4-569b-807c-9981cc1f508f', null, array['17']::text[], '**The correct answer is 17.** The function is defined by $f(x) = 5 +\sqrt{x}$. To evaluate $f(144)$, substitute $x = 144$ into the definition: $f(144) = 5 +\sqrt{144}$. Since $\sqrt{144} = 12$, $f(144) = 5 + 12 = 17$. This is a direct substitution and simplification.
**Faster approach:** Recognize that $\sqrt{144}$ is a commonly memorized square root (12), so immediately compute $5 + 12 = 17$ without intermediate work. For similar problems, substitute and simplify by recalling basic square roots.'),
  ('c3213018-66eb-5fa0-8f3d-e59106993014', 0, null, '**Choice A is correct.** Rearrange the equation: $7x - 4y = -84 ⇒ -4y = -84 - 7x ⇒ y = \frac{7x + 84}{4}$. For $x = 0$, $y = \frac{84}{4} = 21$. For $x = 4$, $y = \frac{7(4) + 84}{4} = \frac{28 + 84}{4} = 28$. For $x = 8$, $y = \frac{56 + 84}{4} = 35$. Those three pairs match the table in choice A.
**Choice B is incorrect.** For $x = 0$ the equation gives $y = 21$, but choice B lists $y = 35$, so the first pair does not satisfy the equation.
**Choice C is incorrect.** Choice C swaps roles of $x$ and $y$; its listed $x$ values (21, 28, 35) do not produce the listed $y$ values when substituted into the equation.
**Choice D is incorrect.** Like C, D has $x$ values 21, 28, 35 but lists $y$ values 8, 4, 0; substituting one of those $x$ values into $y = (7x + 84)/4$ does not yield the corresponding $y$.
**Faster approach:** Solve for $y$ once to get $y = \frac{7}{4}x + 21$, then either plug each given $x$ into this formula or note that when $x$ increases by 4, $y$ increases by 7 — use that pattern to check tables quickly.'),
  ('ad2f07d1-247e-578e-b839-0a16a4f5eb9d', 2, null, '**Choice C is correct.** The weight $x$ equals density times volume, so $x = 160 \cdot V$. Because the volume satisfies $12.7 < V < 15.7$, multiplying each part of that inequality by $160$ (a positive number) gives $160(12.7) < x <$ $160(15.7)$, which is choice C.
**Choice A is incorrect.** That choice subtracts the volume bounds from 160, which has no physical meaning here and does not produce weight (weight is density times volume, not 160 minus volume).
**Choice B is incorrect.** That choice adds 160 to the volume bounds; weight is density times volume, not density plus volume, so the inequality is wrong.
**Choice D is incorrect.** That choice divides 160 by the volume bounds; dividing would give density if 160 were the weight, but here 160 is the density and weight equals density times volume, so division is incorrect.
**Faster approach:** Multiply the given volume-interval endpoints by the density (160) to convert volume bounds directly into weight bounds.'),
  ('05b3aa9c-0a46-5028-9003-5038a8bb55b6', 2, null, '**Choice C is correct.** Start with the given equation $46 = 16 + 2(x - 8)$. Subtract $16$ from both sides to isolate $2(x - 8)$: $46 - 16 = 2(x - 8)$, so $30 = 2(x - 8)$. Thus the value of $2(x - 8)$ is $30$, which matches Choice C.
**Choice A is incorrect.** If $2(x - 8)$ were $16$, then the right side would be $16 + 16 = 32$, not $46$, so A is not consistent with the equation.
**Choice B is incorrect.** If $2(x - 8) = 23$, the sum $16 + 23 = 39$, which does not equal $46$, so B is wrong.
**Choice D is incorrect.** If $2(x - 8) = 38$, then $16 + 38 = 54$, not $46$, so D is incorrect.
**Faster approach:** Immediately subtract $16$ from both sides of $46 = 16 + 2(x - 8)$ to get $2(x - 8) = 46 -$ $16 = 30$ — one subtraction yields the answer without solving for $x$.'),
  ('d31c568a-ba3d-508b-b008-1472c61fcd90', 0, null, '**Choice A is correct.** Setting the two expressions for $y$ equal gives $x^{2} + 1.7 = 1.7 - x$, so $x^{2} + x = 0$ and $x(x + 1) = 0$. Thus $x = 0$ and $x = -1$, with corresponding $y$ values $y = 1.7$ and $y = 2.7$. The parabola $y =$ $x^{2} + 1.7$ opens upward with vertex at $(0,1.7)$, and the line $y = 1.7 - x$ has slope $-1$ and $y$‑intercept $1.7$, so it passes through $(0,1.7)$ and $(-1,2.7)$. Choice A is the graph that shows an upward parabola whose vertex lies on the $y$‑axis at about $1.7$ and a line with slope $-1$ passing through that vertex and the point left and above it.
**Choice B is incorrect.** In B the parabola and line do not share the vertex on the $y$‑axis; the parabola’s vertex is shifted right, so it does not match $y = x^{2} + 1.7$ and $y = 1.7 - x$.
**Choice C is incorrect.** C shows a parabola with a much lower vertex and different vertical position and intersections that do not match $y$‑intercepts $1.7$ and the intersection points $(0,1.7)$ and $(-1,2.7)$.
**Choice D is incorrect.** D places the parabola’s vertex and the line’s intersections at different coordinates (the vertex is not at $(0,1.7)$), so it does not represent the given system.
**Faster approach:** Solve $x^{2} + 1.7 = 1.7 - x$ to get $x(x + 1) = 0$, so the intersections are $x = 0$ and $x = -1$. Immediately check which graph has the parabola vertex at $(0,1.7)$ and a line with slope $-1$ through $(0,1.7)$ and $(-1,2.7)$.'),
  ('7ea3d3c5-1b7d-53c9-a764-6daf5f966787', 2, null, '**Choice C is correct.** In any triangle the measures of the three interior angles sum to $180°$. Here $\angle A = 47°$, $\angle B = 90°$, and $\angle C = (\frac{k}{2})°$. So $47 + 90 + \frac{k}{2} = 180$. Combining the known angles gives $137 + \frac{k}{2} = 180$, so $\frac{k}{2} =$ $43$ and $k = 86$, which matches choice C.
**Choice A is incorrect.** That choice gives $k = 43$, which would make $\angle C = 21.5°$ and the three angles would not sum to $180°$ with the given values.
**Choice B is incorrect.** If $k = 45$ then $\angle C = 22.5°$, and $47 + 90 + 22.5 \ne 180$, so it is not valid.
**Choice D is incorrect.** If $k = 94$ then $\angle C = 47°$, producing $47 + 90 + 47 = 184°$, which is impossible for a triangle.
**Faster approach:** Use the angle-sum rule $A + B + C = 180°$ immediately, substitute the two given angles, subtract their sum from $180°$ to find $\angle C$, then set $\angle C = \frac{k}{2}$ and solve for $k$.'),
  ('518db9ab-66b3-576b-abd0-986f6c6fcbb9', null, array['81/20']::text[], '**The correct answer is 81/20.** To solve for the discounted price of each remaining shirt, follow these steps:
First, determine the retail price of each shirt. The wholesale price is \$5.00, and the retail price is $270%$ of the wholesale price. Calculate the retail price as follows:
\$$\text{Retail} \text{Price} = 5.00 \times (\frac{270}{100}) = 5.00 \times 2.70 = 13.50.$
Next, find the discounted price. The remaining shirts are marked at a discounted price that is $70%$ off the retail price. The discount amount can be calculated as:
\$$\text{Discount} = 13.50 \times (\frac{70}{100}) = 13.50 \times 0.70 = 9.45.$
Now, subtract the discount from the retail price to find the final discounted price:
\$$\text{Discounted} \text{Price} = 13.50 - 9.45 = 4.05.$
To express \$4.05 as a fraction, convert it to:
$4.05 = \frac{405}{100} = \frac{81}{20}.$
Thus, the discounted price of each remaining shirt is $\frac{81}{20}$ dollars.'),
  ('29449225-b4e3-5a13-b1c5-5483876825c9', 1, null, '**Choice B is correct.** The line of best fit passes near grid intersections that make it easy to estimate rise/run. For example, it goes roughly through (1, 12) and (13, 0). The slope is $\frac{0-12}{13-1} = \frac{-12}{12} = -1$, which is closest to $-1.1$ of the offered choices.
**Choice A is incorrect.** $-3.3$ is much steeper (more negative) than the observed line; the plotted line drops only about 12 units in $y$ while $x$ changes about 12–15 units, so slope magnitude is near 1, not 3.3.
**Choice C is incorrect.** $1.1$ is positive; the line clearly slopes downward left to right, so a positive slope cannot be correct.
**Choice D is incorrect.** $3.3$ is positive and steep; it conflicts with the line’s negative, much shallower decline.
**Faster approach:** Pick two grid-intersection points on the drawn line (where it crosses tick marks) and compute slope as $Δy/Δx$ — this yields an immediate, accurate estimate for every scatterplot line-fit question.'),
  ('025f36e5-e5b3-58c3-a2cf-edca5521ce69', null, array['6']::text[], '**The correct answer is 6.** Factoring $y^{4}$ from the given expression gives $72y^{5} - 48y^{4} = y^{4}(72y - 48)$. The expression is also written as $ry^{4}(12y - 8)$, so $r(12y - 8) = 72y - 48$. Equating coefficients of like terms gives $12r = 72$, so $r = 6$ (and $-8r = -48$ also yields $r = 6$, confirming the result).
**Alternate check:** Multiply $6y^{4}(12y - 8) = 6y^{4} \cdot 12y - 6y^{4} \cdot 8 = 72y^{5} - 48y^{4}$, which matches the original expression.
**Faster approach:** Factor the greatest common factor $y^{4}$ immediately to get $y^{4}(72y - 48)$, then compare the parentheses to $r(12y - 8)$ and match coefficients (or divide $72y - 48$ by $12y - 8$) to find $r$ quickly.'),
  ('0ab95b69-88d3-5990-a55c-ee986392ab40', 0, null, '**Choice A is correct.** The ordered pair $(x,y) = (1,58)$ means that when $x = 1$ (1 day after the company went public), the model gives $y = 58$ (an estimated stock price of \$58). Substituting $x = 1$ into $y = 0.25x^{2} -$ $6.5x + 64.25$ yields $y = 0.25(1)^{2} - 6.5(1) + 64.25 = 0.25 - 6.5 + 64.25 = 58$, which matches the point.
**Choice B is incorrect.** It reverses the coordinates: $(58,1)$ would mean 58 days corresponds to a price of \$1, not $(1,58)$.
**Choice C is incorrect.** It asserts a constant increase of \$58 per day, which would describe a linear rate; the model is quadratic, and the pair $(1,58)$ does not indicate a daily constant increase.
**Choice D is incorrect.** It claims a rate of \$1 every 58 days; an ordered pair does not express a rate of change, and the numbers are misinterpreted.
**Faster approach:** Remember that in a model $y = f(x)$ the ordered pair $(x,y)$ means "input $x$, output $y$"—so plug $x = 1$ into the formula or read it as 1 day corresponds to \$58.'),
  ('fd028115-e71b-5415-9e14-68df377d3b27', 3, null, '**Choice D is correct.** If $r$ identical objects have total mass $t$, then each object has mass $\frac{t}{r}$. For $146r$ objects, the total mass is $146r \cdot \frac{t}{r} = 146t$, so choice D is the correct expression.
**Choice A is incorrect.** $146 - t$ subtracts $t$ from 146; it does not reflect scaling the number of objects by 146 or use the per-object mass $\frac{t}{r}$.
**Choice B is incorrect.** $146 + t$ adds the numbers rather than multiplying the total mass by 146; it does not represent $146$ times the original mass.
**Choice C is incorrect.** $\frac{t}{146}$ would represent dividing the original total mass by 146, the opposite of the needed scaling.
**Faster approach:** Find mass per object $= \frac{t}{r}$, then multiply by $146r$; the $r$ cancels, giving $146t$—so look for simple proportional scaling.'),
  ('8a912cb4-5ca8-5d13-b2dc-757ca4b8b391', 2, null, '**Choice C is correct.** To solve for the value of $7x^{2}$, we first need to manipulate the given equation $\frac{42}{x} = 7x$. We start by eliminating the fraction. Multiply both sides by $x$ (assuming $x \ne 0$):
$42 = 7x^{2}.$
Next, we isolate $x^{2}$ by dividing both sides by $7$:
$x^{2} = \frac{42}{7} = 6.$
Then, we want to find the value of $7x^{2}$. To do this, we multiply both sides of the equation $x^{2} = 6$ by $7$:
$7x^{2} = 7 \cdot 6 = 42.$
Thus, the final answer is $7x^{2} = 42$, confirming that the correct answer is C.
Now, let’s briefly examine why each of the other options is incorrect:
**Option A: 6** — This is the value of $x^{2}$, not $7x^{2}$.
**Option B: 7** — This does not relate to our calculations and is incorrect, as we’ve derived $7x^{2}$ to be $42$. **Option D: 294** — This is much larger than the derived value of $7x^{2}$, and thus is also incorrect.'),
  ('18262712-779e-5460-b2af-2397a1a2a107', null, array['6/5']::text[], '**The correct answer is 6/5.** Identify two points on line k from the grid: the left marked point is at (-6, 0) and the right marked point is at (0, -5). The slope of k is $m_{k} = \frac{-5-0}{0-(-6)} = \frac{-5}{6}$. A line perpendicular to k has slope equal to the negative reciprocal of $m_{k}$, so $m_{j} = -1/m_{k} = -1/(-5/6) = 6/5$.
**Faster approach:** Read two clear grid points on line k, compute its slope, then take the negative reciprocal to get the perpendicular slope. This procedure works for every perpendicular-slope question.'),
  ('4623a5de-1f32-5ea7-84ec-ffcac0db1993', null, array['9']::text[], '**The correct answer is 9.** The y-intercept of a graph is the point where the graph crosses the y-axis, which occurs at $x = 0$. Evaluate $f$ at $x = 0$: $f(0) = -9(0) + 9 = 9$. Thus the y-coordinate of the y-intercept is $9$.
**Faster approach:** Immediately substitute $x = 0$ into the linear equation written in slope-intercept form $y =$ $mx + b$; the constant term $b$ is the y-intercept. Here the function is $y = -9x + 9$, so $b = 9$ without any further calculation.'),
  ('599b089b-09ec-5563-95c3-08ff5ea4da2c', null, array['526.1']::text[], '**The correct answer is 526.1.** To find the corresponding temperature in kelvins for a substance at 467.33 degrees Fahrenheit, we start with the given equation:
$h = \frac{9(v - 273.15)}{5} + 12$
We need to rearrange this equation to solve for $v$ when $h = 467.33$. Here are the steps:
First, substitute $h = 467.33$ into the equation:
$467.33 = \frac{9(v - 273.15)}{5} + 12$
Next, isolate the fraction on the right side by subtracting 12 from both sides:
$467.33 - 12 = \frac{9(v - 273.15)}{5}$
$455.33 = \frac{9(v - 273.15)}{5}$
Now, multiply both sides by 5 to eliminate the fraction:
$5 \times 455.33 = 9(v - 273.15)$
$2276.65 = 9(v - 273.15)$
Next, divide both sides by 9:
$\frac{2276.65}{9} = v - 273.15$
$252.96 = v - 273.15$
Finally, add 273.15 to both sides to solve for $v$:
$v = 252.96 + 273.15$
$v = 526.11$
Therefore, rounding to one decimal place, the corresponding temperature in kelvins is:
$v \approx 526.1$
Thus, the corresponding temperature, in kelvins, of the substance at 467.33 degrees Fahrenheit is 526.1.'),
  ('3d2947f4-79b7-5804-9f14-0f76b60c9e20', 1, null, '**Choice B is correct.** The standard equation of a circle with center $(h,k)$ and radius $r$ is $(x - h)^{2} + (y - k)^{2} =$ $r^{2}$. Here $h = 16$, $k = 17$, and $r = 7k$, so $r^{2} = (7k)^{2} = 49k^{2}$, giving $(x - 16)^{2} + (y - 17)^{2} = 49k^{2}$.
**Choice A is incorrect.** It has $49k$ on the right-hand side, which would be $r^{2}$ only if $r =\sqrt{49k} = 7\sqrt{k}$, not $r =$ $7k$.
**Choice C is incorrect.** It sets $(x - 16)^{2} + (y - 17)^{2} = 7k$, which equals $r$ (not $r^{2}$) when $r = 7k$, so it does not match the required $r^{2}$.
**Choice D is incorrect.** It puts $7x^{2}$ on the right side, which depends on $x$ and therefore cannot represent a circle centered at a fixed point; the right side must be the constant $r^{2}$.
**Faster approach:** Immediately write $(x - 16)^{2} + (y - 17)^{2} = (7k)^{2}$ and simplify to $49k^{2}$ — always square the radius to get the right-hand side of a circle equation.'),
  ('15270349-d99c-55f0-b5ae-fd8c59f9c21a', null, array['52/53']::text[], '**The correct answer is 52/53.** In the right triangle RST the hypotenuse RT has length 53 and the vertical leg RS has length $\sqrt{105}$. Use the Pythagorean theorem to find the horizontal leg TS: $TS^{2} = RT^{2} - RS^{2} = 53^{2} -$ $(\sqrt{105})^{2} = 2809 - 105 = 2704$, so $TS =\sqrt{2704} = 52$. The sine of angle R is opposite over hypotenuse, so $\sin R = \frac{TS}{RT} = \frac{52}{53}$.
**Faster approach:** Recognize that with a right triangle you can immediately use Pythagorean theorem to find the side opposite angle R, then compute $\sin R = \text{opposite}/\text{hypotenuse}$. This avoids computing angles and works for all right-triangle trig problems.'),
  ('c12e5fc0-ccfa-50a2-8a6d-b49e9a1d0150', 2, null, '**Choice C is correct.** When two similar figures have corresponding linear dimensions in ratio $k$, their areas are in ratio $k^{2}$. Here each side of $PQRS$ is $2$ times the corresponding side of $ABCD$, so the area of $PQRS$ is $2^{2} = 4$ times the area of $ABCD$. Thus the area is $4 \times 5 = 20$ square centimeters.
**Choice A is incorrect.** 7 does not equal 4 times 5, so it does not follow from the similarity and scaling factor given.
**Choice B is incorrect.** 10 is only twice 5; it would be correct if linear dimensions scaled by $\sqrt{2}$, not by 2.
**Choice D is incorrect.** 25 is $5^{2}$, which would be the area if the linear scale factor were 5, but the given scale factor is 2.
**Faster approach:** Immediately square the linear scale factor: $2^{2} = 4$, then multiply the original area by 4 to get the new area.'),
  ('84e6dac6-feb4-5b09-9955-41e27942a863', 1, null, '**Choice B is correct.** The quadratic $r(t) = -2t^{2} + 55t$ opens downward, so its maximum is at the vertex. The vertex occurs at $t = -\frac{b}{2a} = \frac{55}{4}$. Evaluating $r$ there gives $r(\frac{55}{4}) = 55 \cdot \frac{55}{4} - 2(\frac{55}{4})^{2} = \frac{55^{2}}{4} - 2 \cdot \frac{55^{2}}{16} =$ $\frac{55^{2}}{8}$. Thus the maximum of $s(t) = r(t) + 1$ is $1 + \frac{55^{2}}{8}= 1 + 2(\frac{55}{4})^{2}$, which matches choice B. **Choice A is incorrect.** It equals $1 + (55/2)^{2} = 1 + \frac{55^{2}}{4}$, which is twice the correct $\frac{55^{2}}{8}$ term, so it is too large. **Choice C is incorrect.** It gives $1 - 2(55/4)^{2}$, which subtracts instead of adding the positive maximum value of $r(t)$, so it is wrong.
**Choice D is incorrect.** It is $1 - 2(55/2)^{2}$, both negative and numerically far from the true maximum. **Faster approach:** Use the vertex formula $t = -\frac{b}{2a}$ for $at^{2} + bt + c$ to get the maximizing $t$, then plug into the quadratic once to compute the maximum (then add 1 for $s$).')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

