  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('5d1a8ac9-7e7a-5017-b702-050197193720', '5647c47f-7046-5f0d-a782-7f371de24b86', 'As part of a science experiment on evaporation, Ella measured the height of water in a glass over a period of time. The function $f(x) = 39 - 0.1x$ gives the estimated height in centimeters (cm), of the water in the glass $x$ days after the start of the experiment. Which of the following is the best interpretation of $39$ in this context?', '["The estimated height, in cm, of the water at the start of the experiment", "The estimated height, in cm, of the water at the end of the experiment", "The estimated change in the height, in cm, of the water each day", "The estimated number of days for all the water to evaporate"]'::jsonb, 1, null),
  ('58af131c-0875-5092-90f9-fc27f33b75ca', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The roofs on the buildings of a public garden are designed to allow water to drain into the garden. The table shows the relationship between the area $x$, in square feet, of a roof and the amount of water $f(x)$, in gallons, drained from the roof into the garden over a certain period of time. Which equation could define $f$?', '["$f(x) = 0.6x$", "$f(x) = 1.8x$", "$f(x) = 2268.0x$", "$f(x) = 0.56x$"]'::jsonb, 2, '| Area (square feet) | Water (gallons) |
| $2520$ | $4536$ |
| $3780$ | $6804$ |
| $5040$ | $9072$ |'),
  ('612b1d52-af69-5dca-9d26-8273a519fa4c', '5647c47f-7046-5f0d-a782-7f371de24b86', 'In 2010, a skating team had a total of $35$ skaters, each classified as either advanced or intermediate. From 2010 to 2020, the number of advanced skaters on the team increased by approximately $53%$, and the number of intermediate skaters on the team increased by approximately $44%$. The total number of skaters on the team increased by approximately $49%$. Which equation best represents this situation, where $a$ represents the number of advanced skaters on the team in 2010 and $b$ represents the number of intermediate skaters on the team in 2010?', '["$1.53a + 1.49b = 35(1.44)$", "$1.49a + 0.53b = 35(1.44)$", "$1.53a + 1.44b = 35(1.49)$", "$1.44a + 1.53b = 35(1.49)$"]'::jsonb, 3, null),
  ('fa2af7ad-37f3-51af-b71b-20f1a7609b30', '5647c47f-7046-5f0d-a782-7f371de24b86', '$b - 72 = \frac{x}{y}$
The given equation relates the positive numbers $b$, $x$, and $y$. Which equation correctly expresses $x$ in terms of $b$ and $y$?', '["$x = \\frac{b-72}{y}$", "$x = by - 72$", "$x = \\frac{by-72}{y}$", "$x = by - 72y$"]'::jsonb, 4, null),
  ('98530ea8-b714-5a17-8fd6-e19d398337bc', '5647c47f-7046-5f0d-a782-7f371de24b86', 'One of the two equations in a system of linear equations is given. $y = \frac{2}{7}x + 3$. The system has infinitely many solutions. If the second equation in the system is $y = mx + b$, where $m$ and $b$ are constants, what is the value of $b$?', '["-3", "$\\frac{1}{3}$", "$-\\frac{1}{3}$", "$3$"]'::jsonb, 5, null),
  ('4f8de223-6a80-51e5-bbd7-38cbe8a20568', '5647c47f-7046-5f0d-a782-7f371de24b86', '$y = 6x + 16$
$-7x - y = 36$
What is the solution $(x,y)$ to the given system of equations?', '["$(-4,-8)$", "$(\\frac{20}{13}, \\frac{-80}{13})$", "$(4,40)$", "$(20,136)$"]'::jsonb, 6, null),
  ('4a8cdedb-6902-579e-9e12-cf48ce1657d2', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The histograms summarize the distributions of scores for team A and team B. Which statement best compares the standard deviations of scores for these teams?', '["The standard deviation of scores for team A is less than the standard deviation of scores for team B.", "The standard deviation of scores for team A is greater than the standard deviation of scores for team B.", "The standard deviation of scores for team A is equal to the standard deviation of scores for team B.", "There is not enough information to compare the standard deviations."]'::jsonb, 7, '![figure](/q/oct24/009.webp)'),
  ('df764eb8-dc4e-5799-b0ca-d6e15b53a830', '5647c47f-7046-5f0d-a782-7f371de24b86', '$x^{2} - 5x - 24 = 0$
What is the sum of the solutions to the given equation?', '[]'::jsonb, 8, null),
  ('4049180d-8978-5392-9f02-f534cb08d5ee', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The graph of $y = f(x)$ is shown, where $f(x) = ab^{x} + c$, and $a$, $b$, and $c$ are constants. For how many values of $x$ does $f(x) = 0$?', '["Three", "Two", "One", "Zero"]'::jsonb, 9, '![figure](/q/oct24/010.webp)'),
  ('4da61193-2137-555b-b9cc-917fbd00ccfb', '5647c47f-7046-5f0d-a782-7f371de24b86', 'To study fluctuations in leaf water potential, samples of wood were taken from 22 trees and cut in the shape of a cube. The length of the edge of one of these cubes is $3.000$ centimeters. This cube has a density of $0.250$ grams per cubic centimeter. What is the mass of this cube, in grams?', '[]'::jsonb, 10, null),
  ('423608d3-63ed-546a-a144-96b849d36ca2', '5647c47f-7046-5f0d-a782-7f371de24b86', 'Function $f$ is a quadratic function where $f(-20) = 0$ and $f(-4) = 0$. The graph of $y = f(x)$ in the xy-plane has a vertex at $(r,-64)$. What is the value of $r$?', '[]'::jsonb, 11, null),
  ('5f9519bb-d178-5c91-88d4-62d44d438e3d', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The function $f$ gives the product of a number, $x$, and a number that is $91$ more than $x$. Which equation defines $f$?', '["$f(x) = x^{2} + x + 91$", "$f(x) = x^{2} + 91$", "$f(x) = x^{2} + 91x$", "$f(x) = x^{2} + 91x + 91$"]'::jsonb, 12, null),
  ('d32d6e86-1813-5cce-80ba-2f43f6629866', '5647c47f-7046-5f0d-a782-7f371de24b86', '$-2x^{2} + 20x + c = 0$
In the given equation, $c$ is a constant. The equation has exactly one solution. What is the value of $c$?', '["$-68$", "$-50$", "$-32$", "$0$"]'::jsonb, 13, null),
  ('23482a4e-574a-5edf-a583-bfe27cde6d77', '5647c47f-7046-5f0d-a782-7f371de24b86', '$y = 2x^{2} - 15x + 23$
$y = x + a$
In the given system of equations, $a$ is a constant, The graphs of the equations in the given system intersect at exactly one point, $(x,y)$, in the xy-plane. What is the value of $x$?', '["$-9$", "$-4$", "$4$", "$9$"]'::jsonb, 14, null),
  ('57ebd711-9fe8-585b-817a-2b1f96554b0c', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The positive number $a$ is $2.352%$ of the sum of the positive numbers $b$ and $c$, and $b$ is $84%$ of $c$. What percent of $b$ is $a$?', '["$5.152%$", "$2.436%$", "$51.52%$", "$24.36%$"]'::jsonb, 15, null),
  ('abe1636c-7503-5eac-a6f6-9f1803a23a37', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The functions $f$ and $g$ are defined by the given equations below, where $x > 0$. Which of the following equations displays, as a constant or coefficient, the minimum value of the function it defines, where $x \ge 0$?
I. $f(x) = 18(1.4)^{x+5}$
II. $g(x) = 18(1.16)(1.4)^{x+3}$', '["I only", "II only", "I and II", "Neither I nor II"]'::jsonb, 16, null),
  ('8c204e5d-780f-578a-8bb3-e442ba63ed18', '5647c47f-7046-5f0d-a782-7f371de24b86', 'In the given equation, $s$ and $r$ are constants, and $s > 0$. If the equation has infinitely many solutions, what is the value of $s$?
$\frac{12x + 28}{4} - \frac{s}{13} = r(x - 8)$', '[]'::jsonb, 17, null),
  ('e95e55b5-929a-54e3-a1b4-37d96c80de18', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The perimeter of an isosceles right triangle is $18 + 18\sqrt{2}$ inches. What is the length, in inches, of the hypotenuse of this triangle?', '["$9$", "$9\\sqrt{2}$", "$18$", "$18\\sqrt{2}$"]'::jsonb, 18, null),
  ('9497598b-9249-5ca5-90f8-c1c29b2ba70b', '5647c47f-7046-5f0d-a782-7f371de24b86', 'A right triangular pyramid has exactly six edges. Each of these edges is $96$ centimeters long. If the surface area of the pyramid is $k\sqrt{3}$ square centimeters, what is the value of $k$?', '[]'::jsonb, 19, null),
  ('e41d4900-a72b-5363-8ff4-8e420b287664', '5647c47f-7046-5f0d-a782-7f371de24b86', 'The cost of renting a piece of construction equipment for up to $5$ days is \$270 for the first day and \$135 for each additional day. Which of the following equations gives the cost $y$, in dollars, of renting the equipment for $x$ days, where $x$ is a positive integer and $x \le 5$?', '["$y = 135x + 135$", "$y = 270x - 135$", "$y = 270x + 135$", "$y = 135x + 170$"]'::jsonb, 20, null),
  ('030418c9-856b-5987-b30d-cba232988316', '5647c47f-7046-5f0d-a782-7f371de24b86', 'A line intersects two parallel lines, forming four acute angles and four obtuse angles. The measure of one of these eight angles is $(7x - 250)°$. The sum of the measures of four of the eight angles is $k°$. Which of the following could NOT be equivalent to $k$, for all values of $w$?', '["$-14x + 1,540$", "$14x - 320$", "$-28x + 1,720$", "$360$"]'::jsonb, 21, null),
  ('0765545a-a36a-51bb-a104-1e52c00e05c0', '5647c47f-7046-5f0d-a782-7f371de24b86', '$7x + 4y = 3$
$35x + 20y = 15$
For each real number $r$, which of the following points lies on the graph of each equation in the xy-plane for the given system?', '["$(\\frac{r}{5} + 3,-\\frac{r}{5} + 15)$", "$(-\\frac{4r}{7} + \\frac{3}{7}r)$", "$(r, \\frac{7r}{4} + \\frac{3}{4})$", "$(r,-\\frac{4r}{7} + \\frac{3}{7})$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('5d1a8ac9-7e7a-5017-b702-050197193720', 0, null, '**Choice A is correct.** In the linear function $f(x) = 39 - 0.1x$, the constant term $39$ is the value of $f$ when $x =$ $0$, i.e., the height at the start of the experiment (0 days). That is the natural interpretation of the y-intercept: the initial estimated height in centimeters.
**Choice B is incorrect.** The ‘‘end of the experiment’’ would correspond to some positive value of $x$, not $x = 0$, so the end height is not represented by the constant term unless the experiment lasts 0 days.
**Choice C is incorrect.** The estimated change in height per day is given by the slope, $-0.1$, not $39$; $-0.1$ cm per day indicates a daily decrease.
**Choice D is incorrect.** The number of days until all water evaporates would solve $39 - 0.1x = 0$, giving $x =$ $390$, not $39$; thus $39$ is not a time value.
**Faster approach:** For any linear model $f(x) = b + mx$, immediately interpret $b$ as the initial amount (value at $x = 0$) and $m$ as the rate of change per unit $x$.'),
  ('58af131c-0875-5092-90f9-fc27f33b75ca', 1, null, '**Choice B is correct.** The data show a constant rate of water per square foot. Compute the ratio $f(x)/x$ using the first row: $4536/2520 = 1.8$, so $f(x) = 1.8x$. The other rows give the same ratio ($6804/3780 = 1.8$, $9072/5040 = 1.8$), confirming the linear rule $f(x) = 1.8x$.
**Choice A is incorrect.** $f(x) = 0.6x$ would produce $0.6(2520) = 1512$, not $4536$, so it does not match the table.
**Choice C is incorrect.** $f(x) = 2268.0x$ is far too large; for $x = 2520$ it would give $2268(2520)$, not $4536$, so it does not fit the data.
**Choice D is incorrect.** $f(x) = 0.56x$ would give $0.56(2520) = 1411.2$, which does not equal $4536$, so it does not match the table.
**Faster approach:** For any table showing a linear relation, divide the output by the input for one row to get the constant multiplier; if consistent across rows, that value is the coefficient in $f(x) = mx$.'),
  ('612b1d52-af69-5dca-9d26-8273a519fa4c', 2, null, '**Choice C is correct.** If $a$ and $b$ are the numbers of advanced and intermediate skaters in 2010, then in 2020 there are $1.53a$ advanced (a 53% increase) and $1.44b$ intermediate (a 44% increase). The total in 2020 is given as a 49% increase over 35, i.e. $35(1.49)$. So the equation describing the 2020 total is $1.53a + 1.44b = 35(1.49)$ .
**Choice A is incorrect.** It has $1.49b$ on the left and $1.44$ multiplying 35 on the right; this swaps the 44% and 49% factors and so does not reflect the given percentage changes.
**Choice B is incorrect.** It places the 1.49 factor on $a$ and 0.53 on $b$, which reverses both percentages and also uses 0.53 instead of 1.53, so it does not match the described increases.
**Choice D is incorrect.** It assigns the 44% and 53% multipliers to the wrong groups (putting 1.44 with $a$ and 1.53 with $b$), so it does not model the stated changes.
**Faster approach:** Convert each percent change to a multiplicative factor ($1+$change), write the new counts as factors times the old counts, and set their sum equal to the total old count times its multiplicative factor.'),
  ('fa2af7ad-37f3-51af-b71b-20f1a7609b30', 3, null, '**Choice D is correct.** Starting with $b - 72 = \frac{x}{y}$, multiply both sides by $y$ to clear the denominator: $y(b - 72) =$ $x$. Distribute to get $x = by - 72y$, which matches choice D.
**Choice A is incorrect.** $x = \frac{b-72}{y}$ would be the result of dividing the left side by $y$, not multiplying—this reverses the required operation and does not satisfy the original equation.
**Choice B is incorrect.** $x = by - 72$ fails to account for the factor of $y$ multiplying $72$; multiplying $b - 72$ by $y$ yields $by - 72y$, not $by - 72$.
**Choice C is incorrect.** $x = \frac{by-72}{y}$ simplifies to $b - \frac{72}{y}$, which is not equivalent to $y(b - 72)$ and therefore does not match the original equation.
**Faster approach:** Whenever an equation has a variable in a denominator, multiply both sides by that denominator to clear fractions; this directly yields $x = y(b - 72)$ for every problem of this type.'),
  ('98530ea8-b714-5a17-8fd6-e19d398337bc', 3, null, '**Choice D is correct.** For a system of two linear equations to have infinitely many solutions, the two equations must represent the same line. The first line is $y = \frac{2}{7}x + 3$, so the second line must have the same slope and the same $y$-intercept: $m = \frac{2}{7}$ and $b = 3$. Thus $b = 3$, which is Choice D.
**Choice A is incorrect.** If $b = -3$ the second line would have a different $y$-intercept, so even if the slope matched the first line the lines would be distinct and could be parallel (no solutions) rather than identical.
**Choice B is incorrect.** $b = \frac{1}{3}$ does not match the given line’s intercept $3$, so the lines would not be the same. **Choice C is incorrect.** $b = -\frac{1}{3}$ is also a different intercept, so the two equations would not coincide.
**Faster approach:** For infinitely many solutions, require identical slope and intercept; read off $b$ directly from the given equation ($b = 3$).'),
  ('4f8de223-6a80-51e5-bbd7-38cbe8a20568', 0, null, '**Choice A is correct.** Substitute $y = 6x + 16$ into $-7x - y = 36$: $-7x - (6x + 16) = 36$, so $-13x - 16 = 36$, hence $-13x = 52$ and $x = -4$. Then $y = 6(-4) + 16 = -24 + 16 = -8$, giving $(-4,-8)$ which matches choice A.
**Choice B is incorrect.** Those fractions correspond to $x = 20/13 \approx 1.54$, which does not satisfy $-13x = 52$, so it is not a solution.
**Choice C is incorrect.** If $x = 4$ then $y = 6(4) + 16 = 40$, but $x = 4$ does not satisfy $-13x = 52$ (it would give $-52 \ne 52$), so the pair fails the second equation.
**Choice D is incorrect.** If $x = 20$ then $y = 136$ fits the first equation but $x = 20$ does not satisfy $-13x = 52$, so the second equation is not satisfied.
**Faster approach:** Use direct substitution of $y$ from the first equation into the second to get a single linear equation in $x$, then solve for $x$ and back-substitute for $y$.'),
  ('4a8cdedb-6902-579e-9e12-cf48ce1657d2', 0, null, '**Choice A is correct.** Standard deviation measures how spread out scores are around the mean. The histogram for team A has almost all scores clustered tightly near the center (many scores around 40–70) with no extreme tails, so scores deviate relatively little from the mean. Team B’s histogram has substantial bars at the low end (near 0–10) and high end (near 90–100) as well as intermediate bars, indicating a much wider spread of values. Thus team A has the smaller standard deviation.
**Choice B is incorrect.** It claims team A’s standard deviation is greater, but team A’s scores are more tightly clustered about the center than team B’s, so A cannot have the larger standard deviation.
**Choice C is incorrect.** Equality would require similar spread and tails for both teams; the histograms show clearly different spreads (B has long tails and extreme values), so the standard deviations are not equal.
**Choice D is incorrect.** The histograms provide enough information about the relative spread (concentration versus tails) to determine which standard deviation is larger, so we do have enough information.
**Faster approach:** For any histogram comparison, visually compare how concentrated the bars are around the center and look for long tails or extreme-value bars. The distribution with tighter central clustering and smaller tails always has the smaller standard deviation.'),
  ('df764eb8-dc4e-5799-b0ca-d6e15b53a830', null, array['5']::text[], '**The correct answer is 5.** For a quadratic $ax^{2} + bx + c = 0$, the sum of the solutions equals $-\frac{b}{a}$. Here $a = 1$ and $b = -5$, so the sum is $-(-5)/1 = 5$.
**Faster approach:** Immediately apply the relation $\text{sum} \text{of} \text{roots} = -\frac{b}{a}$ for any quadratic; no factoring or solving for individual roots is needed.'),
  ('4049180d-8978-5392-9f02-f534cb08d5ee', 3, null, '**Choice D is correct.** The graph is an exponential of the form $f(x) = ab^{x} + c$ and shows a horizontal asymptote at $y = c = -8$ and the curve lying between $y = -8$ and $y = 0$ for all shown $x$ (it approaches $-8$ from above as $x → \infty$ and never reaches $0$). Because every plotted value of $f(x)$ is negative and the asymptote is below zero, there is no $x$ for which $f(x) = 0$.
**Choice A is incorrect.** Three intersections would require the graph to cross the $x$-axis three times; the curve never reaches $y = 0$.
**Choice B is incorrect.** Two intersections would require two distinct $x$ with $f(x) = 0$; the graph does not cross the $x$-axis at all.
**Choice C is incorrect.** One intersection would mean the curve crosses the $x$-axis once; the curve stays strictly below $y = 0$ and so has no zeros.
**Faster approach:** For any function $f(x) = ab^{x} + c$ first identify the horizontal asymptote $y = c$ and check whether the entire plotted curve lies above or below $y = 0$. If the curve and the asymptote are both on the same side of the $x$-axis and the curve never reaches $0$, then $f(x) = 0$ has zero solutions.'),
  ('4da61193-2137-555b-b9cc-917fbd00ccfb', null, array['27/4']::text[], '**The correct answer is 6.75.** Volume of a cube with edge length $3.000$ cm is $V = 3.000^{3} = 27.000 \text{cm}^{3}$. Mass equals density times volume, so mass $= 0.250 \text{g}/\text{cm}^{3} \times 27.000 \text{cm}^{3} = 6.75 \text{g}$.
**Faster approach:** Multiply density by volume directly: compute $3^{3} = 27$ and then $27 \times 0.25 = 6.75$, avoiding extra decimals when possible.'),
  ('423608d3-63ed-546a-a144-96b849d36ca2', null, array['-12']::text[], '**The correct answer is -12.** For a quadratic function, the axis of symmetry (the x-coordinate of the vertex) is the midpoint of its two x-intercepts. The given zeros are $-20$ and $-4$, so the midpoint is $\frac{-20+(-4)}{2} = \frac{-24}{2} =$ $-12$. Thus $r = -12$.
**Faster approach:** Always use that for a quadratic with real roots $a$ and $b$, the vertex x-coordinate is $(a + b)/2$. Compute the average of the two roots to get the vertex’s x-value immediately.'),
  ('5f9519bb-d178-5c91-88d4-62d44d438e3d', 2, null, '**Choice C is correct.** The phrase “product of a number, $x$, and a number that is $91$ more than $x$” means multiply $x$ by $(x + 91)$. Distribute to get $x(x + 91) = x^{2} + 91x$, which matches choice C.
**Choice A is incorrect.** $x^{2} + x + 91$ would come from multiplying $x$ by $(x + 1)$ and then adding $91$, which does not represent the given product.
**Choice B is incorrect.** $x^{2} + 91$ omits the $x$ factor multiplying $91$; it would be $x^{2} + 91$ only if the task were to add 91 to $x^{2}$, not to multiply by $(x + 91)$.
**Choice D is incorrect.** $x^{2} + 91x + 91$ adds an extra $91$ term that is not produced by the product $x(x + 91)$.
**Faster approach:** Use distribution/FOIL immediately: $x(x + 91) = x^{2} + 91x$. For any similar prompt “product of $x$ and $(x + k)$,” always distribute to obtain $x^{2} + kx$.'),
  ('d32d6e86-1813-5cce-80ba-2f43f6629866', 1, null, '**Choice B is correct.** A quadratic has exactly one real solution when its discriminant is zero. For $-2x^{2} +$ $20x + c = 0$ the discriminant is $b^{2} - 4ac = 20^{2} - 4(-2)(c) = 400 + 8c$. Setting this equal to 0 gives $400 +$ $8c = 0$, so $8c = -400$ and $c = -50$.
**Choice A is incorrect.** If $c = -68$, the discriminant would be $400 + 8(-68) = 400 - 544 = -144$, which is negative, so there would be no real solutions.
**Choice C is incorrect.** If $c = -32$, the discriminant would be $400 + 8(-32) = 400 - 256 = 144$, which is positive, so there would be two distinct real solutions, not one.
**Choice D is incorrect.** If $c = 0$, the discriminant is $400 + 0 = 400$, positive, yielding two distinct real solutions.
**Faster approach:** Always set the discriminant $b^{2} - 4ac = 0$ for "exactly one real solution" and solve for the constant; this works for any quadratic.'),
  ('23482a4e-574a-5edf-a583-bfe27cde6d77', 2, null, '**Choice C is correct.** Substitute $y = x + a$ into $y = 2x^{2} - 15x + 23$ to get $2x^{2} - 16x + (23 - a) = 0$. The system has exactly one intersection when this quadratic has a double root, so its discriminant is $0$: $(-16)^{2} -$ $4(2)(23 - a) = 0$. That gives $256 - 8(23 - a) = 0 ⇒ 72 + 8a = 0 ⇒ a = -9$. The double root is $x = -\frac{B}{2A} =$ $-\frac{-16}{2 \cdot 2} = \frac{16}{4} = 4$, so $x = 4$.
**Choice A is incorrect.** $x = -9$ is not the double root computed from the quadratic; substituting would not satisfy the double-root formula $x = -B/(2A)$.
**Choice B is incorrect.** $x = -4$ also does not match the double root found by $x = -\frac{B}{2A} = 4$, so it cannot be the unique intersection $x$-coordinate.
**Choice D is incorrect.** $x = 9$ is not the value of the double root; it does not equal $-B/(2A)$ for the quadratic $2x^{2} - 16x + (23 - a) = 0$ when the discriminant is zero.
**Faster approach:** For a line tangent to a parabola, set the quadratic formed by equating them and require the discriminant $b^{2} - 4ac = 0$, then compute the double root with $x = -b/(2a)$. This works for any such tangency problem.'),
  ('57ebd711-9fe8-585b-817a-2b1f96554b0c', 0, null, '**Choice A is correct.** Let a = 0.02352(b + c) and b = 0.84c. Then b + c = 1.84c, so a = 0.02352(1.84c) = 0.0432768c. Thus a/b = 0.0432768c/(0.84c) = 0.0432768/0.84 = 0.05152 = 5.152%, so a is 5.152% of b.
**Choice B is incorrect.** 2.436% is about half of the correct value; it would result from a calculation error such as dividing by 1.84 instead of multiplying by 1.84 before dividing by 0.84.
**Choice C is incorrect.** 51.52% is 10 times too large; it corresponds to misplacing the decimal point after converting the final decimal 0.05152 to a percent.
**Choice D is incorrect.** 24.36% is also far too large and would come from an arithmetic mistake in combining the given percentages and ratios.
**Faster approach:** Use ratios. Write a/b = 2.352%·(b+c)/b = 2.352%·(1 + c/b). With b = 0.84c, c/b = 1/0.84, so a/b = 2.352%·(1 + 1/0.84) = 2.352%·2.190476... = 5.152%. Alternatively, set c = 100 (so b = 84) to compute quickly.'),
  ('abe1636c-7503-5eac-a6f6-9f1803a23a37', 3, null, '**Choice D is correct.** Both functions have base $1.4 > 1$, so each is strictly increasing for $x \ge 0$ and attains its minimum at the smallest allowed $x$, namely $x = 0$. For I, $f(0) = 18(1.4)^{5}$, which is not equal to the coefficient $18$ that appears in the formula. For II, $g(0) = 18(1.16)(1.4)^{3}$, which is not equal to the displayed coefficient $18(1.16)$. Thus neither equation actually displays its minimum value as a standalone constant or coefficient.
**Choice A is incorrect.** For I the minimum is $18(1.4)^{5}$, not the written coefficient $18$, so the equation does not display its minimum as a constant or coefficient.
**Choice B is incorrect.** For II the minimum is $18(1.16)(1.4)^{3}$, not the written coefficient $18(1.16)$, so the equation does not display its minimum as a constant or coefficient.
**Choice C is incorrect.** Neither I nor II displays its minimum value as a constant or coefficient, so both cannot be correct.
**Faster approach:** For any exponential $a \cdot b^{x+c}$ with base $b > 1$, the minimum on $x \ge 0$ occurs at $x = 0$. Evaluate at $x = 0$ to get the true minimum and check whether that exact number appears as a standalone constant/coefficient in the original expression (not hidden inside a factor like $b^{x+c}$). If it does not, the equation does not display its minimum.'),
  ('8c204e5d-780f-578a-8bb3-e442ba63ed18', null, array['403']::text[], '**The correct answer is 403.** For the equation to have infinitely many solutions, the expression must be an identity in $x$, so the coefficients of $x$ and the constant terms must match on both sides. Rewrite the left side: $\frac{12x+28}{4} = 3x + 7$, so the equation becomes $3x + 7 - \frac{s}{13} = r(x - 8) = rx - 8r$. Equating coefficients of $x$ gives $3 = r$. Substituting $r = 3$ and equating constant terms gives $7 - \frac{s}{13} = -8(3) = -24$. Solving $7 - \frac{s}{13} =$ $-24$ yields $-\frac{s}{13} = -31$, so $\frac{s}{13} = 31$ and $s = 31 \cdot 13 = 403$, which is positive as required.
**Faster approach:** Rearrange to compare like terms: match the $x$-coefficients to find $r$, then match constant terms to solve for $s$; this two-step coefficient comparison works for any linear identity in one variable.'),
  ('e95e55b5-929a-54e3-a1b4-37d96c80de18', 2, null, '**Choice C is correct.** Let each leg have length $x$; then the hypotenuse is $x\sqrt{2}$ and the perimeter is $2x +$ $x\sqrt{2} = x(2 +\sqrt{2})$. Set this equal to $18 + 18\sqrt{2} = 18(1 +\sqrt{2})$, so $x = \frac{18(1 + \sqrt{2})}{2 + \sqrt{2}}$. Multiply numerator and denominator by the conjugate $2 -\sqrt{2}$ to get $x = 9(1 +\sqrt{2})(2 -\sqrt{2}) = 9\sqrt{2}$. The hypotenuse is $x\sqrt{2} =$ $9\sqrt{2} \cdot\sqrt{2} = 18$.
**Choice A is incorrect.** A hypotenuse of $9$ is too small; using the correct relation $P = x(2 +\sqrt{2})$ leads to $x =$ $9\sqrt{2}$ for the legs, so the hypotenuse is $18$, not $9$.
**Choice B is incorrect.** $9\sqrt{2}$ is the length of each leg, not the hypotenuse; multiplying by an additional $\sqrt{2}$ gives $18$ for the hypotenuse.
**Choice D is incorrect.** $18\sqrt{2}$ is twice the correct hypotenuse; it would correspond to legs of length $18$, which would produce a larger perimeter than given.
**Faster approach:** Write perimeter as $(2 +\sqrt{2})\cdot$(leg). Compute leg = $P/(2 +\sqrt{2})$ and clear the radical by multiplying numerator and denominator by the conjugate $2 -\sqrt{2}$; then multiply the leg by $\sqrt{2}$ to get the hypotenuse. This avoids trial and error and works for any isosceles right triangle.'),
  ('9497598b-9249-5ca5-90f8-c1c29b2ba70b', null, array['9216']::text[], '**The correct answer is 9216.** A triangular pyramid with all six edges equal is a regular tetrahedron, so all four faces are congruent equilateral triangles with side length $96$. The area of one equilateral triangle of side $s$ is $\frac{\sqrt{3}}{4}s^{2}$. With $s = 96$ the area of one face is $\frac{\sqrt{3}}{4}(96)^{2}$, and the total surface area (four faces) is $4 \cdot \frac{\sqrt{3}}{4}(96)^{2} =\sqrt{3} \cdot$ $96^{2}$.
**Faster approach:** Recognize that six equal edges force a regular tetrahedron, so multiply the area formula for one equilateral triangle, $\frac{\sqrt{3}}{4}s^{2}$, by 4 to get $\sqrt{3}s^{2}$; then compute $96^{2} = 9216$.'),
  ('e41d4900-a72b-5363-8ff4-8e420b287664', 0, null, '**Choice A is correct.** The total cost is $270$ for the first day plus $135$ for each additional day. For $x$ days there are $x - 1$ additional days, so $y = 270 + 135(x - 1) = 270 + 135x - 135 = 135x + 135$, which matches choice A.
**Choice B is incorrect.** $y = 270x - 135$ would give $270$ per day then subtract $135$, so for $x = 1$ it gives $135$ instead of the required $270$.
**Choice C is incorrect.** $y = 270x + 135$ implies the first day costs $405$ (set $x = 1$), which is too large; it treats every day as $270$ plus an extra $135$.">
**Choice D is incorrect.** $y = 135x + 170$ gives $305$ for $x = 1$, which does not match the stated $270$ first-day cost.
**Faster approach:** Plug in $x = 1$ to each answer choice; the correct formula must give $y = 270$. This immediately eliminates any choice that doesn’t equal $270$ when $x = 1$.'),
  ('030418c9-856b-5987-b30d-cba232988316', 0, null, '**Choice A is correct.** Let the acute angle measure be $a$ and the obtuse measure be $b = 180 - a$. One of these equals $7x - 250$. The sum of any four angles depends on how many acute angles $n$ are chosen (0≤n≤4): $k =$ $na + (4 - n)b = 720 - 180n + 2(n - 2)a$, but easier is to list cases. If all four are acute: $4a = 28x - 1000$. If three acute and one obtuse: $3a + b = 2a + 180 = 14x - 320$ (Choice B). If two of each: $2a + 2b = 360$ (Choice D). If one acute and three obtuse: $a + 3b = 540 - 2a = 1040 - 14x$. If all four obtuse: $4b = 1720 -$ $28x$ (Choice C). The expression in A, $-14x + 1540$, does not match any of these possible sums, so A cannot represent $k$ for all $x$.
**Choice B is incorrect.** $14x - 320$ equals $3a + b$, which is achievable when three acute and one obtuse angle are chosen.
**Choice C is incorrect.** $-28x + 1720$ equals $4b$, the sum when all four chosen angles are the obtuse ones.
**Choice D is incorrect.** $360$ is $2a + 2b$, the sum when two acute and two obtuse angles are chosen.
**Faster approach:** Enumerate sums by counting how many acute angles (0–4) are included; compute each sum in terms of $a = 7x - 250$ (and $b = 180 - a$). This yields the only possible algebraic forms for $k$, so any choice not matching one is impossible.'),
  ('0765545a-a36a-51bb-a104-1e52c00e05c0', 1, null, '**Choice B is correct.** This choice represents the point where both equations in the system are satisfied. To verify, we first check if the equations are equivalent. Notice that the second equation,
$35x + 20y = 15$
, is actually a multiple of the first equation,
$7x + 4y = 3$
. Specifically, if we multiply both sides of the first equation by 5, we get:
$5(7x + 4y) = 5(3) ⟹ 35x + 20y = 15.$
Thus, both equations describe the same line in the xy-plane. For choice B, we can express it as $(x,y) =$ $(r,-\frac{4r}{7} + \frac{3}{7})$. To check if this point lies on the line defined by either equation, we substitute $x = r$ into the first equation:
$7(r) + 4(-\frac{4r}{7} + \frac{3}{7}) = 3.$
Calculating the left side:
$7r - \frac{16r}{7} + \frac{12}{7} = \frac{49r}{7} - \frac{16r}{7} + \frac{12}{7} = \frac{33r + 12}{7}.$
Setting this equal to 3:
$\frac{33r + 12}{7} = 3 ⟹ 33r + 12 = 21 ⟹ 33r = 9 ⟹ r = \frac{9}{33} = \frac{3}{11},$
which indicates that this point works for some r. Next, let’s examine the other choices:
**Choice A**: The expression $(\frac{r}{5} + 3,-\frac{r}{5} + 15)$ introduces different coefficients that do not satisfy the linear relationship established by the original equations.
**Choice C**: In $(r, \frac{7r}{4} + \frac{3}{4})$, substituting into the first equation similarly leads to an equation that does not hold true for all values of $r$ as it does not maintain the linear relationship.
**Choice D**: This option also does not preserve the required balance when substituted into either equation, leading to inconsistencies for most values of $r$.
In summary, only choice B produces a point that satisfies both equations in the system, confirming its correctness.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
